<?php require 'vendor/autoload.php'; use PHPMailer\PHPMailer\PHPMailer; $mail = new PHPMailer(true); $mail->SMTPDebug = 2; $mail->isSMTP(); $config = require 'mail-config.php'; $mail->Host = $config['smtp_host']; $mail->Port = $config['smtp_port']; $mail->SMTPAuth = true; $mail->Username = $config['smtp_username']; $mail->Password = $config['smtp_password']; $mail->SMTPSecure = 'tls'; $mail->setFrom($config['from_email'], $config['from_name']); $mail->addAddress($config['to_email']); $mail->Subject = 'Test'; $mail->Body = 'Test'; try { $mail->send(); echo 'OK'; } catch (Exception $e) { echo $e->getMessage(); }